from agent_tools.tests.fixtures.windows_cp117_historical_factory.context import HistoricalFactoryTestCase as HistoryCase, provider as historical_provider
"""Complete source-authenticated CP117 read-only server ingress regression."""
import ast,base64,gzip,json,unittest
from pathlib import Path
from . import test_windows_cp117_base_source_refresh as fixture
OLD_MAIN_BINDING_GZIP=''
CURRENT_MAIN_BINDING_GZIP=''
class ServerReadMainBindingTests(HistoryCase):
 def census_source(self):
  source=fixture.DirectFixtureServerReadTests().factory_source()
  for a,b,text in reversed(json.loads(gzip.decompress(base64.b64decode(SERVER_CENSUS_EDITS)))):source=source[:a]+text+source[b:]
  return source
 def run_actual(self,compressed,*,corrupt=False):
  traw=Path(fixture.__file__).read_bytes();eraw=self.census_source().encode();braw=Path(__file__).read_bytes()
  if corrupt:eraw=eraw.replace(b"SERVER_PROVENANCE_SHA=",b"FOREIGN_PROVENANCE_SHA=",1)
  namespace={'ast':ast,'base64':base64,'gzip':gzip,'json':json,'traw':traw,'eraw':eraw,'braw':braw}
  exec(compile(gzip.decompress(base64.b64decode(compressed)),'actual-retained-main-ingress','exec'),namespace)
  return namespace
 def test_actual_old_loader_red_current_authenticated_edits_green(self):
  with self.assertRaisesRegex(ValueError,'readback-tested-source'):self.run_actual(OLD_MAIN_BINDING_GZIP)
  value=self.run_actual(CURRENT_MAIN_BINDING_GZIP)
  self.assertEqual(value['tested'],self.census_source())
 def test_actual_current_predicate_refuses_foreign_factory(self):
  with self.assertRaisesRegex(ValueError,'readback-tested-source'):self.run_actual(CURRENT_MAIN_BINDING_GZIP,corrupt=True)

