   root=Path(td).resolve();(root/'.runtime/parity-evidence/case').mkdir(parents=True,mode=0o700)
   p=root/'factory.py';p.write_text(self.census_source());p.chmod(0o600);n={'__name__':'actual-saved-case','__file__':str(p)};exec(compile(p.read_bytes(),str(p),'exec'),n)
   cap=n['AuthorityCapture'](root,'case');events=copy.deepcopy(saved['events'])
   try:
    for index,item in enumerate(events):item['pin']=cap.create(n['DOWNLOAD_CORRELATION']+'-event-%d.json'%index,json.dumps(item['event'],sort_keys=True).encode())
    sha=events[0]['event']['sourceSha256'];args=(saved['value'],events,saved['status'],source,n['DOWNLOAD_NONCE'],sha,saved['value']['qemu'],cap)
    with self.assertRaisesRegex(ValueError,'download-validator-closure'):n['admit_download'](*args)
    exec(compile(CENSUS_ADMISSION_REPAIR_SOURCE,'actual-fixed-admission','exec'),n)
    self.assertIs(n['admit_download'](*args),True);json.dumps(saved['value'])
    for label,changed in [('foreign-import',source.replace('from typing import Mapping','from pathlib import Mapping',1)),('class',source.replace('from typing import Mapping','class Foreign: pass',1))]:
     with self.assertRaisesRegex(ValueError,'download-validator-closure',msg=label):n['admit_download'](saved['value'],events,saved['status'],changed,n['DOWNLOAD_NONCE'],sha,saved['value']['qemu'],cap)
    bad=copy.deepcopy(saved['value']);bad['facts']['facts']['download']['serverReady']=True
    with self.assertRaises(ValueError):n['admit_download'](bad,events,saved['status'],source,n['DOWNLOAD_NONCE'],sha,saved['value']['qemu'],cap)
   finally:cap.close()

