SAME8484_CURRENT_VERIFY_SOURCE="def verify():\n    held = {}\n    parents = {}\n\n    def generation(z):\n        return [z.st_dev, z.st_ino, z.st_mode, z.st_uid, z.st_gid, z.st_nlink, z.st_size, z.st_mtime_ns, z.st_ctime_ns]\n    try:\n        for name, pin in INPUTS.items():\n            p = Path(name)\n            fd = os.open(p, os.O_RDONLY | os.O_NOFOLLOW)\n            held[name] = fd\n            if generation(os.fstat(fd)) != pin['generation']:\n                raise ValueError('same8484-held-source-drift')\n            parent = str(p.parent)\n            if parent not in parents:\n                pfd = os.open(p.parent, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)\n                parents[parent] = (pfd, generation(os.fstat(pfd))[:5])\n        for name, pin in INPUTS.items():\n            p = Path(name)\n            if name == BUNDLE_PATH:\n                with n['_held_bundle'](p) as (stream, current, guard):\n                    if current != pin:\n                        raise ValueError('same8484-bundle-drift')\n                    guard()\n            elif pin['generation'][6] == 0:\n                cap = AuthorityCapture(root, p.parent.name)\n                try:\n                    r._local_read(cap, p.name, pin)\n                finally:\n                    cap.close()\n            elif bound(p, private=pin['generation'][2] & 511 == 384) != pin:\n                raise ValueError('same8484-input-drift')\n        for name, fd in held.items():\n            if generation(os.fstat(fd)) != INPUTS[name]['generation'] or generation(Path(name).lstat()) != INPUTS[name]['generation']:\n                raise ValueError('same8484-pure-source-drift')\n        for parent, (pfd, pin) in parents.items():\n            if generation(os.fstat(pfd))[:5] != pin or generation(Path(parent).lstat())[:5] != pin:\n                raise ValueError('same8484-parent-drift')\n    finally:\n        for fd in held.values():\n            os.close(fd)\n        for pfd, _ in parents.values():\n            os.close(pfd)\n"
